import {esc,phraseText} from './ui.js';

// Keep long polite endings readable beside a 44px speaker, without changing the line.
const parts={
 '気になっています。':['気に','なっています。'],
 '結論の部分だけなら':['結論の部分','だけなら'],
 '小さくしませんか。':['小さく','しませんか。'],
 'お願いできますか。':['お願い','できますか。'],
 'おそれがあるので、':['おそれが','あるので、'],
 '確認しませんか。':['確認','しませんか。'],
 'いったん見送って、':['いったん','見送って、'],
 '試してみた上で、':['試してみた','上で、'],

 'うれしいんですが、':['うれしい','んですが、'],
 '遠慮しておきます。':['遠慮して','おきます。'],
 '六時以降でしたら、':['六時以降','でしたら、'],
 'お手伝いできます。':['お手伝い','できます。'],
 '持っていきます。':['持って','いきます。'],
 '持っていきましょうか。':['持って','いきましょうか。'],
 'ありがとうございます。':['ありがとう','ございます。']
};
export const dialogueText=(line,phrases,lang)=>lang==='ko'?esc(line):phraseText(line,(phrases||[line]).flatMap(phrase=>parts[phrase]||[phrase]));
